import itertools

def is_all_interval_series(p):
    n = len(p)
    diffs = [abs(p[i+1] - p[i]) for i in range(n-1)]
    return sorted(diffs) == list(range(1, n))

def find_all_interval_series(n):
    for p in itertools.permutations(range(n)):
        if is_all_interval_series(p):
            return p
    return None

# Since n=11 is small enough for a backtracking search, but maybe too large for itertools.permutations(11!)
# 11! = 39,916,800. This might be slow but manageable. Let's try a more efficient approach.

def solve_all_interval(n):
    def backtrack(current_p, used_nums, used_diffs):
        if len(current_p) == n:
            return current_p

        last = current_p[-1]
        for next_val in range(n):
            if next_val not in used_nums:
                diff = abs(next_val - last)
                if diff not in used_diffs and diff > 0:
                    used_nums.add(next_val)
                    used_diffs.add(diff)
                    res = backtrack(current_p + [next_val], used_nums, used_diffs)
                    if res:
                        return res
                    used_nums.remove(next_val)
                    used_diffs.remove(diff)
        return None

    for start_node in range(n):
        res = backtrack([start_node], {start_node}, set())
        if res:
            return res
    return None

print(solve_all_interval(11))
